/* Kompetenzknoten: die fachlichen Einheiten, in denen Jurist:innen tatsächlich
   denken – „Stellvertretung", „objektive Zurechnung", „Relationstechnik".

   Warum nicht einfach Kapitel? Weil ein Kapitel eine Seite im Buch ist, aber
   keine Fähigkeit. Wer § 164 BGB gelesen hat, kann noch keine Vollmacht prüfen.
   Der Beherrschungsgrad eines Knotens speist sich deshalb aus vier Quellen:
   gelesen (Verstehen), Fälle (Anwenden), Karten (Behalten), Quiz (Kontrolle).

   Zuordnung von Inhalten zu Knoten über drei Wege, in dieser Reihenfolge:
     normen      – Normzitate im Inhalt (härtestes Signal)
     kapitel     – Regex auf den Kapiteltitel
     stichworte  – Begriffe im Titel oder Text

   `relevanz` folgt der Examensrelevanz: hoch = Dauerbrenner, mittel =
   regelmäßig, basis = Grundlage. `verwechslung` nennt die typische
   Verwechslung; daraus baut die Fehleranalyse ihre Rückmeldung. */

export const STUFEN_NAMEN = [
  { ab: 0, id: "offen", name: "noch offen", text: "noch nicht begonnen" },
  { ab: 0.15, id: "angelesen", name: "angelesen", text: "gelesen, aber noch nicht angewandt" },
  { ab: 0.4, id: "grundlagen", name: "Grundlagen", text: "Aufbau sitzt, Anwendung wackelt" },
  { ab: 0.6, id: "sicher", name: "sicher", text: "Schema und Fälle laufen" },
  { ab: 0.78, id: "klausurreif", name: "klausurreif", text: "auch unter Zeitdruck belastbar" },
  { ab: 0.9, id: "examensreif", name: "examensreif", text: "sitzt samt Streitständen und Ausnahmen" },
];

export function stufeFuer(wert) {
  let aus = STUFEN_NAMEN[0];
  for (const s of STUFEN_NAMEN) if (wert >= s.ab) aus = s;
  return aus;
}

